import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry respects the image aspect (512 × 320 → 1.6 × 1)
  const geometry = new PlaneGeometry(1.6, 1);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Async texture load (material updated when ready)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Store active GSAP timelines for cleanup
  const activeTimelines = [];

  // Hover lift (rise‑in) – subtle 0.15 unit lift
  const hoverEnter = () => {
    const tl = gsap.timeline();
    tl.to(root.position, {
      y: root.position.y + 0.15,
      duration: 0.3,
      ease: 'power3.out',
    });
    activeTimelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.timeline();
    tl.to(root.position, {
      y: root.position.y - 0.15,
      duration: 0.2,
      ease: 'power2.inOut',
    });
    activeTimelines.push(tl);
  };

  // Click press‑down + emit navigation event
  const clickHandler = () => {
    const tl = gsap.timeline();
    tl.to(
      root.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      },
      0,
    ).to(
      root.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.2,
        ease: 'elastic.out(1,0.4)',
      },
      '+=0.05',
    );
    activeTimelines.push(tl);
    ctx.emit('hub-journal.select');
  };

  // Attach interaction handlers (adapter will forward events)
  root.userData.handlers = {
    hover: { enter: hoverEnter, leave: hoverLeave },
    click: clickHandler,
  };

  // Apply cinematic primitives defined in config
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    if (ctx.primitives[prim.name]) {
      const instance = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();

    // Kill GSAP timelines
    activeTimelines.forEach((tl) => tl.kill());

    // Cleanup primitives
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    });
  };

  return root;
}
